#include <iostream>
#include <cmath>

int main() {
    int year = 0;
    if (std::cin >> year) {
        // Leap year condition: divisible by 4 and not 100, or divisible by 400
        bool is_leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        if (is_leap) {
            std::cout << year << " is a leap year\n";
        } else {
            std::cout << year << " is not a leap year\n";
        }
    }

    double a = 0.0, b = 0.0, c = 0.0;
    if (std::cin >> a >> b >> c) {
        if (a == 0.0) {
            std::cout << "Not a quadratic equation\n";
        } else {
            double delta = b * b - 4.0 * a * c;
            if (delta < 0.0) {
                std::cout << "No real roots\n";
            } else if (delta == 0.0) {
                double x = -b / (2.0 * a);
                std::cout << "Double root: " << x << "\n";
            } else {
                double x1 = (-b + std::sqrt(delta)) / (2.0 * a);
                double x2 = (-b - std::sqrt(delta)) / (2.0 * a);
                std::cout << "Root 1: " << x1 << ", Root 2: " << x2 << "\n";
            }
        }
    }
    return 0;
}

