#include <iostream>

int main() {
    int month = 0;
    int year = 0;
    if (std::cin >> month >> year) {
        int days = 0;
        switch (month) {
            case 1:
            case 3:
            case 5:
            case 7:
            case 8:
            case 10:
            case 12:
                days = 31;
                break;
            case 4:
            case 6:
            case 9:
            case 11:
                days = 30;
                break;
            case 2: {
                bool is_leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
                days = is_leap ? 29 : 28;
                break;
            }
            default:
                days = -1;
                break;
        }

        if (days == -1) {
            std::cout << "Invalid month: " << month << "\n";
        } else {
            std::cout << "Month " << month << " of year " << year << " has " << days << " days\n";
        }
    }
    return 0;
}
